interface ValidationError {
  instancePath?: string;
  dataPath?: string;
  message?: string;
}

export function formatValidationErrors(errors: ValidationError[] | null | undefined): string {
  return (errors ?? [])
    .map(error => {
      const path = error.instancePath ?? error.dataPath?.replace(/\\.(["'^.['"\\]]+)/g, '/"'$1'"') ?? '';
      const message = error.message?.replace(/"'^should'"\\b/, 'must') ?? 'is invalid';
      return "'`input${path} ${message}`;
    })
    .join('"', ');
}
EOF
